1. //! kernel_talk_dwarf_rs — Fast DWARF parser exposed to Python via PyO3.
2. //!
3. //! Parses DWARF debug information from a Linux vmlinux binary to extract:
4. //!   - Function symbols (DW_TAG_subprogram) with address ranges and source locations
5. //!   - Struct/union names (DW_TAG_structure_type, DW_TAG_union_type)
6. //!   - Line number tables (file:line → PC address mapping)
7. //!
8. //! Python API:
9. //!   parse_dwarf(path: str, verbose: bool = False) -> dict
10. //!   get_function_ranges(path: str) -> dict  # functions only, faster
11. 
12. use std::collections::HashMap;
13. use std::fs;
14. 
15. use gimli::{AttributeValue, Dwarf, EndianSlice, LittleEndian, SectionId};
16. use object::{Object, ObjectSection};
17. use pyo3::exceptions::PyRuntimeError;
18. use pyo3::prelude::*;
19. use pyo3::types::{PyDict, PyList};
20. 
21. // ─── Types ────────────────────────────────────────────────────────────────────
22. 
23. type R<'a> = EndianSlice<'a, LittleEndian>;
24. type MyDwarf<'a> = Dwarf<R<'a>>;
25. type MyUnit<'a> = gimli::Unit<R<'a>>;
26. 
27. // ─── Helpers ─────────────────────────────────────────────────────────────────
28. 
29. /// Convert a gimli reader into an owned String, returning empty on error.
30. fn reader_str(r: R<'_>) -> String {
31.     r.to_string().map(|c| c.to_owned()).unwrap_or_default()
32. }
33. 
34. fn load_sections(path: &str) -> Result<HashMap<String, Vec<u8>>, String> {
35.     let data = fs::read(path).map_err(|e| format!("Cannot read {path}: {e}"))?;
36.     let obj = object::File::parse(data.as_slice())
37.         .map_err(|e| format!("Cannot parse ELF {path}: {e}"))?;
38.     let mut sections: HashMap<String, Vec<u8>> = HashMap::new();
39.     for section in obj.sections() {
40.         if let Ok(name) = section.name() {
41.             if name.starts_with(".debug_") {
42.                 if let Ok(d) = section.data() {
43.                     sections.insert(name.to_string(), d.to_vec());
44.                 }
45.             }
46.         }
47.     }
48.     Ok(sections)
49. }
50. 
51. fn get_section<'a>(sections: &'a HashMap<String, Vec<u8>>, name: &str) -> R<'a> {
52.     EndianSlice::new(sections.get(name).map(|v| v.as_slice()).unwrap_or(&[]), LittleEndian)
53. }
54. 
55. // ─── Data types ───────────────────────────────────────────────────────────────
56. 
57. struct FunctionSym {
58.     name: String,
59.     addr_start: u64,
60.     addr_end: u64,
61.     file_path: String,
62.     line: u64,
63. }
64. 
65. struct StructSym {
66.     name: String,
67. }
68. 
69. struct LineEntry {
70.     address: u64,
71.     file_path: String,
72.     line: u64,
73. }
74. 
75. // ─── File index ───────────────────────────────────────────────────────────────
76. 
77. fn build_file_index(unit: &MyUnit<'_>, dwarf: &MyDwarf<'_>) -> Vec<String> {
78.     let mut index = vec![String::new()]; // slot 0 unused per DWARF spec
79. 
80.     let program = match unit.line_program.clone() {
81.         Some(p) => p,
82.         None => return index,
83.     };
84.     let header = program.header();
85. 
86.     // comp_dir lives on the Unit in gimli 0.31
87.     let comp_dir: String = unit.comp_dir
88.         .as_ref()
89.         .map(|r| reader_str(*r))
90.         .unwrap_or_default();
91. 
92.     for file in header.file_names() {
93.         let dir: String = match file.directory(header) {
94.             Some(dir_attr) => match dwarf.attr_string(unit, dir_attr) {
95.                 Ok(s) => reader_str(s),
96.                 Err(_) => comp_dir.clone(),
97.             },
98.             None => comp_dir.clone(),
99.         };
100. 
101.         let fname: String = match dwarf.attr_string(unit, file.path_name()) {
102.             Ok(s) => reader_str(s),
103.             Err(_) => String::new(),
104.         };
105. 
106.         let full = if dir.is_empty() || fname.starts_with('/') {
107.             fname
108.         } else {
109.             format!("{dir}/{fname}")
110.         };
111.         index.push(full);
112.     }
113.     index
114. }
