116. // ─── Function extraction ──────────────────────────────────────────────────────
117. 
118. fn extract_functions(unit: &MyUnit<'_>, dwarf: &MyDwarf<'_>, file_index: &[String], out: &mut Vec<FunctionSym>) {
119.     let mut entries = unit.entries();
120.     while let Ok(Some((_delta, entry))) = entries.next_dfs() {
121.         if entry.tag() != gimli::DW_TAG_subprogram { continue; }
122. 
123.         // Skip declarations (no code)
124.         if let Ok(Some(a)) = entry.attr(gimli::DW_AT_declaration) {
125.             if let AttributeValue::Flag(true) = a.value() { continue; }
126.         }
127. 
128.         let name: String = match entry.attr(gimli::DW_AT_name) {
129.             Ok(Some(a)) => match dwarf.attr_string(unit, a.value()) {
130.                 Ok(s) => reader_str(s),
131.                 Err(_) => continue,
132.             },
133.             _ => continue,
134.         };
135.         if name.is_empty() { continue; }
136. 
137.         let lo_pc: u64 = match entry.attr(gimli::DW_AT_low_pc) {
138.             Ok(Some(a)) => match a.value() {
139.                 AttributeValue::Addr(v) => v,
140.                 _ => continue,
141.             },
142.             _ => continue,
143.         };
144.         if lo_pc == 0 { continue; }
145. 
146.         let hi_pc: u64 = entry.attr(gimli::DW_AT_high_pc).ok().flatten()
147.             .and_then(|a| match a.value() {
148.                 AttributeValue::Addr(v) => Some(v),
149.                 AttributeValue::Udata(offset) => Some(lo_pc + offset),
150.                 _ => None,
151.             })
152.             .unwrap_or(lo_pc);
153. 
154.         let file_idx: usize = entry.attr(gimli::DW_AT_decl_file).ok().flatten()
155.             .and_then(|a| match a.value() {
156.                 AttributeValue::FileIndex(v) => Some(v as usize),
157.                 _ => None,
158.             })
159.             .unwrap_or(0);
160.         let file_path = file_index.get(file_idx).cloned().unwrap_or_default();
161. 
162.         let line: u64 = entry.attr(gimli::DW_AT_decl_line).ok().flatten()
163.             .and_then(|a| match a.value() {
164.                 AttributeValue::Udata(v) => Some(v),
165.                 _ => None,
166.             })
167.             .unwrap_or(0);
168. 
169.         out.push(FunctionSym { name, addr_start: lo_pc, addr_end: hi_pc, file_path, line });
170.     }
171. }
172. 
173. // ─── Struct extraction ────────────────────────────────────────────────────────
174. 
175. fn extract_structs(unit: &MyUnit<'_>, dwarf: &MyDwarf<'_>, out: &mut Vec<StructSym>) {
176.     let mut entries = unit.entries();
177.     while let Ok(Some((_delta, entry))) = entries.next_dfs() {
178.         let tag = entry.tag();
179.         if tag != gimli::DW_TAG_structure_type && tag != gimli::DW_TAG_union_type { continue; }
180. 
181.         if let Ok(Some(a)) = entry.attr(gimli::DW_AT_declaration) {
182.             if let AttributeValue::Flag(true) = a.value() { continue; }
183.         }
184. 
185.         let name: String = match entry.attr(gimli::DW_AT_name) {
186.             Ok(Some(a)) => match dwarf.attr_string(unit, a.value()) {
187.                 Ok(s) => reader_str(s),
188.                 Err(_) => continue,
189.             },
190.             _ => continue,
191.         };
192.         if !name.is_empty() {
193.             out.push(StructSym { name });
194.         }
195.     }
196. }
197. 
198. // ─── Line table extraction ────────────────────────────────────────────────────
