200. fn extract_lines(unit: &MyUnit<'_>, file_index: &[String], out: &mut Vec<LineEntry>) {
201.     let program = match unit.line_program.clone() {
202.         Some(p) => p,
203.         None => return,
204.     };
205.     let mut rows = program.rows();
206.     while let Ok(Some((_header, row))) = rows.next_row() {
207.         if row.end_sequence() { continue; }
208.         let file_idx = row.file_index() as usize;
209.         let file_path = file_index.get(file_idx).cloned().unwrap_or_default();
210.         let line: u64 = row.line().map(|l| l.get()).unwrap_or(0);
211.         out.push(LineEntry { address: row.address(), file_path, line });
212.     }
213. }
