219. fn parse_dwarf(py: Python<'_>, path: &str, verbose: bool, functions_only: bool) -> PyResult<PyObject> {
220.     let sections = load_sections(path).map_err(PyRuntimeError::new_err)?;
221. 
222.     let dwarf = gimli::Dwarf::load(|id: SectionId| -> Result<R<'_>, gimli::Error> {
223.         Ok(get_section(&sections, id.name()))
224.     }).map_err(|e| PyRuntimeError::new_err(format!("DWARF load: {e}")))?;
225. 
226.     let mut functions: Vec<FunctionSym> = Vec::new();
227.     let mut structs: Vec<StructSym> = Vec::new();
228.     let mut lines: Vec<LineEntry> = Vec::new();
229. 
230.     let mut cu_iter = dwarf.units();
231.     let mut cu_count = 0u32;
232. 
233.     while let Ok(Some(header)) = cu_iter.next() {
234.         let unit = match dwarf.unit(header) {
235.             Ok(u) => u,
236.             Err(_) => continue,
237.         };
238.         cu_count += 1;
239.         if verbose && cu_count % 1000 == 0 {
240.             eprintln!("[dwarf-rs] {cu_count} CUs, {} funcs, {} structs",
241.                 functions.len(), structs.len());
242.         }
243. 
244.         let file_index = build_file_index(&unit, &dwarf);
245.         extract_functions(&unit, &dwarf, &file_index, &mut functions);
246. 
247.         if !functions_only {
248.             extract_structs(&unit, &dwarf, &mut structs);
249.             extract_lines(&unit, &file_index, &mut lines);
250.         }
251.     }
252. 
253.     if verbose {
254.         eprintln!("[dwarf-rs] Done: {} CUs, {} functions, {} structs, {} line entries",
255.             cu_count, functions.len(), structs.len(), lines.len());
256.     }
257. 
258.     let result = PyDict::new_bound(py);
259. 
260.     let py_functions = PyList::empty_bound(py);
261.     for f in &functions {
262.         let d = PyDict::new_bound(py);
263.         d.set_item("name", &f.name)?;
264.         d.set_item("addr_start", f.addr_start)?;
265.         d.set_item("addr_end", f.addr_end)?;
266.         d.set_item("file_path", &f.file_path)?;
267.         d.set_item("line", f.line)?;
268.         py_functions.append(&d)?;
269.     }
270.     result.set_item("functions", &py_functions)?;
271. 
272.     let py_structs = PyList::empty_bound(py);
273.     for s in &structs {
274.         let d = PyDict::new_bound(py);
275.         d.set_item("name", &s.name)?;
276.         d.set_item("fields", PyList::empty_bound(py))?;
277.         py_structs.append(&d)?;
278.     }
279.     result.set_item("structs", &py_structs)?;
280. 
281.     let py_lines = PyList::empty_bound(py);
282.     for le in &lines {
283.         let d = PyDict::new_bound(py);
284.         d.set_item("address", le.address)?;
285.         d.set_item("file_path", &le.file_path)?;
286.         d.set_item("line", le.line)?;
287.         py_lines.append(&d)?;
288.     }
289.     result.set_item("line_entries", &py_lines)?;
290. 
291.     Ok(result.into())
292. }
293. 
294. #[pyfunction]
295. #[pyo3(signature = (path, verbose=false))]
296. fn get_function_ranges(py: Python<'_>, path: &str, verbose: bool) -> PyResult<PyObject> {
297.     parse_dwarf(py, path, verbose, true)
298. }
