300. #[pymodule]
301. fn kernel_talk_dwarf_rs(m: &Bound<'_, PyModule>) -> PyResult<()> {
302.     m.add_function(wrap_pyfunction!(parse_dwarf, m)?)?;
303.     m.add_function(wrap_pyfunction!(get_function_ranges, m)?)?;
304.     m.add("__version__", env!("CARGO_PKG_VERSION"))?;
305.     Ok(())
306. }
